+
+/** UC-002: View Veterinarians. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VeterinariansView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.XLARGE);
+
+        Grid<Vet> grid = new Grid<>();
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : vet.specialties().stream()
+                        .map(Specialty::name).collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setKey("specialties").setFlexGrow(2);
+        grid.setSizeFull();
+        grid.setItems(this::fetch, query -> count());
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        // Fetch/count also run after navigation when the visitor scrolls.
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                ui.getInternals().getActiveViewLocation(), exception,
+                NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
